    # ---------------- sim runtime.insert ----------------
    m = lambda k, vi, en=None: a('m.insert.' + k, vi, en)
    m('title', 'Chèn một cây con: top-down hay bottom-up?', 'Inserting a subtree: top-down or bottom-up?')
    m('overview', 'Ví dụ trong KDoc của `Applier.insertTopDown`: chèn node `B` (có hai con `A`, `C`) vào `R`. Chọn thứ tự chèn và kiểu cây: cây báo cho MỌI TỔ TIÊN khi có con mới, hay cây báo cho node mới và CẢ CÂY CON của nó khi nó vào cây. Đếm số lần thông báo.', 'The example from the `Applier.insertTopDown` KDoc: insert node `B` (with two children `A`, `C`) into `R`. Pick the insertion order and the kind of tree: one that notifies EVERY ANCESTOR when a child is added, or one that notifies the new node and ITS WHOLE SUBTREE when it enters the tree. Count the notifications.')
    m('wrapup', 'Cùng ba lần chèn, số thông báo khác nhau tùy thứ tự và tùy loại cây. Cây báo tổ tiên thì chèn bottom-up rẻ hơn (3 so với 5); cây báo cây con thì top-down rẻ hơn (3 so với 5). Vì vậy `Applier` cho cả hai hàm và mỗi loại cây chọn MỘT. Compose UI trên Android chọn bottom-up cho `LayoutNode`.', 'With the same three inserts, the notification count differs by order and by tree type. For a tree that notifies ancestors, bottom-up is cheaper (3 vs 5); for one that notifies the subtree, top-down is cheaper (3 vs 5). That is why `Applier` offers both functions and each tree type picks ONE. Compose UI on Android picks bottom-up for `LayoutNode`.')
    m('simp.1', 'Số thông báo theo đúng ví dụ ba node trong KDoc @296313a4. KDoc nói với cây lớn, số thông báo của thứ tự "sai" tăng nhanh hơn nhiều so với số node.', 'Notification counts follow the three-node example in the KDoc @296313a4 exactly. The KDoc says that for larger trees, the "wrong" order\'s notification count grows much faster than the number of nodes.')
    m('simp.2', 'Ký hiệu R⇐B nghĩa là R được báo B vừa vào; ở kiểu "cây con", chỉ ghi tên node được báo. Lời gọi `down`/`up` được gộp vào bước cho gọn.', 'R⇐B means R is told that B has entered; in "subtree" mode only the notified node\'s name is shown. `down`/`up` calls are merged into the steps for brevity.')
    m('ctl.hint', 'Đổi thứ tự chèn với mỗi kiểu cây và so số thông báo ở cuối.', 'Change the insertion order for each tree type and compare the final notification count.')
    m('ctl.order', 'Thứ tự chèn', 'Insertion order')
    m('ctl.order.topDown', 'Từ trên xuống (insertTopDown)', 'Top-down (insertTopDown)')
    m('ctl.order.bottomUp', 'Từ dưới lên (insertBottomUp)', 'Bottom-up (insertBottomUp)')
    m('ctl.notify', 'Cây báo cho ai khi có node mới', 'Who the tree notifies on a new node')
    m('ctl.notify.ancestors', 'Mọi tổ tiên được báo có con mới', 'Every ancestor is told of the new child')
    m('ctl.notify.subtree', 'Node mới và cả cây con của nó được báo', 'The new node and its whole subtree are told')
