    S = [
        ('start', 'Bắt đầu: R trong cây, B chờ được chèn', 'Start: R is in the tree, B waits to be inserted', 'Composition vừa phát ra node `B` với hai con `A`, `C` (ví dụ: một `Row` mới với hai `Text`). Applier phải đưa chúng vào cây thật.', 'Composition has just emitted node `B` with two children `A`, `C` (for example a new `Row` with two `Text`s). The Applier must put them into the real tree.'),
        ('td1', 'Top-down 1: chèn B vào R', 'Top-down 1: insert B into R', '`insertTopDown` được gọi TRƯỚC khi con của B được tạo. B vào cây ngay. Thông báo đến lúc này: {n}.', '`insertTopDown` is called BEFORE B\'s children are created. B enters the tree right away. Notifications so far: {n}.'),
        ('td2', 'Top-down 2: chèn A vào B', 'Top-down 2: insert A into B', 'B đã ở trong cây, nên A vào cây ngay lúc được chèn. Thông báo đến lúc này: {n}.', 'B is already in the tree, so A enters the tree as soon as it is inserted. Notifications so far: {n}.'),
        ('td3', 'Top-down 3: chèn C vào B', 'Top-down 3: insert C into B', 'Tương tự với C. Thông báo: {n}.', 'The same for C. Notifications: {n}.'),
        ('bu1', 'Bottom-up 1: chèn A vào B (B chưa ở trong cây)', 'Bottom-up 1: insert A into B (B is not in the tree yet)', '`insertBottomUp` được gọi SAU khi con đã được chèn: dựng cây con trước, khi B còn đứng riêng. Thông báo: {n}.', '`insertBottomUp` is called AFTER the children are inserted: the subtree is built first, while B still stands alone. Notifications: {n}.'),
        ('bu2', 'Bottom-up 2: chèn C vào B', 'Bottom-up 2: insert C into B', 'B vẫn chưa ở trong cây. Thông báo: {n}.', 'B is still not in the tree. Notifications: {n}.'),
        ('bu3', 'Bottom-up 3: chèn B (đã đủ con) vào R', 'Bottom-up 3: insert B (complete) into R', 'Cả cây con B, A, C vào cây cùng lúc. Thông báo: {n}.', 'The whole B, A, C subtree enters the tree at once. Notifications: {n}.'),
        ('end.ancTD', 'Kết thúc: 5 thông báo (top-down, báo tổ tiên)', 'The end: 5 notifications (top-down, ancestors)', 'R bị báo ba lần, vì mỗi lần thêm con vào B thì R cũng được báo.', 'R is notified three times, because each child added to B notifies R too.'),
        ('end.ancBU', 'Kết thúc: 3 thông báo (bottom-up, báo tổ tiên)', 'The end: 3 notifications (bottom-up, ancestors)', 'Mỗi node được báo đúng một lần ở chỗ cần: số thông báo tăng tuyến tính theo số node.', 'Each node is notified exactly once where needed: the count grows linearly with the number of nodes.'),
        ('end.subTD', 'Kết thúc: 3 thông báo (top-down, báo cây con)', 'The end: 3 notifications (top-down, subtree)', 'Mỗi node được báo đúng một lần khi nó vào cây.', 'Each node is notified exactly once when it enters the tree.'),
        ('end.subBU', 'Kết thúc: 5 thông báo (bottom-up, báo cây con)', 'The end: 5 notifications (bottom-up, subtree)', 'A và C bị báo hai lần: một lần khi vào B, một lần nữa khi B (mang theo chúng) vào R.', 'A and C are notified twice: once entering B, again when B (carrying them) enters R.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('end.anc', 'Với cây báo tổ tiên, chọn bottom-up. Đây là lý do `UiApplier` của Android chèn trong `insertBottomUp`. [[src:rt-applier-src]] [[src:ui-uiapplier]]', 'For a tree that notifies ancestors, choose bottom-up. That is why Android\'s `UiApplier` inserts in `insertBottomUp`. [[src:rt-applier-src]] [[src:ui-uiapplier]]'),
        ('end.sub', 'Với cây báo cả cây con khi node vào cây, chọn top-down. [[src:rt-applier-src]]', 'For a tree that notifies the subtree when a node enters, choose top-down. [[src:rt-applier-src]]')]:
        m('co.' + k, vi, en)
    a('cap.insert', 'Cây đích: R ở trên cùng đã nằm trong cây; B và hai con A, C cần được chèn. Node sáng lên là node đang được chèn hoặc được báo ở bước đó.', 'The target tree: R at the top is already in the tree; B and its two children A, C must be inserted. Highlighted nodes are the ones being inserted or notified in that step.')

